{
  "project": "cadi-alfa",
  "module": "generador_eventos",
  "description": "Módulo M4: Generador de Eventos. Selecciona, pondera e instancia eventos no históricos basados en el estado del mundo (M1), el estado del protagonista (M2) y la memoria del sistema (M6). Usa plantillas de eventos definidas en Nivel 2 (content/cadiz/config/plantillas_evento.yaml).",
  "functions": [
    {
      "name": "filtrar_eventos",
      "signature": "fn filtrar_eventos(templates: &[EventTemplate], world: &WorldState, player: &PlayerState, memory: &MemoryState) -> Vec<&EventTemplate>",
      "description": "Filtra plantillas de eventos que cumplen las precondiciones de mundo, jugador y etiquetas de desbloqueo (M6). Devuelve una piscina de candidatos.",
      "examples": [
        "let candidatos = filtrar_eventos(&plantillas, &world, &player, &memory);"
      ]
    },
    {
      "name": "ponderar_eventos",
      "signature": "fn ponderar_eventos(candidatos: Vec<&EventTemplate>, world: &WorldState, player: &PlayerState) -> Vec<(f64, &EventTemplate)>",
      "description": "Aplica modificadores de peso a los candidatos: acto_narrativo, perfil_jugador, compromisos_pendientes, espacios_descuidados, distancia_pivote, factor_equilibrio_drama. Devuelve lista de (peso, plantilla).",
      "examples": [
        "let ponderados = ponderar_eventos(candidatos, &world, &player);"
      ]
    },
    {
      "name": "instanciar_evento",
      "signature": "fn instanciar_evento(plantilla: &EventTemplate, world: &WorldState, player: &PlayerState) -> EventInstance",
      "description": "Selecciona NPC del pool (priorizando por deuda o agenda activa), ajusta tono según estado_global/esp_clima, y filtra opciones visibles según visibilidad del jugador. Devuelve EventInstance listo para ser resuelto.",
      "examples": [
        "let evento = instanciar_evento(&plantilla, &world, &player);"
      ]
    },
    {
      "name": "generar_eventos_jornada",
      "signature": "fn generar_eventos_jornada(world: &WorldState, player: &PlayerState, memory: &MemoryState, plantillas: &[EventTemplate], ranuras: usize) -> Vec<EventInstance>",
      "description": "Orquesta el proceso completo: filtra, pondera, selecciona los top N eventos (según ranuras), y los instancia. Usa M6 para registrar en historial y activar cooldowns.",
      "examples": [
        "let eventos = generar_eventos_jornada(&world, &player, &memory, &plantillas, 3);"
      ]
    }
  ],
  "tests": [
    "fn test_filtrar_eventos_excluye_no_cumplen_precondiciones() { let world = WorldState::new(); let player = PlayerState::new(); let memory = MemoryState::new(); let plantillas = vec![EventTemplate { precondiciones: Precondiciones { mundo: vec![(String::from(\"acto_narrativo\"), String::from(\">=\"), String::from(\"2\"))], jugador: vec![], etiquetas_unlock: vec![] }, ..Default::default() }]; let candidatos = filtrar_eventos(&plantillas, &world, &player, &memory); assert!(candidatos.is_empty()); }",
    "fn test_ponderar_eventos_asigna_peso_base() { let world = WorldState { time: TimeState { acto_narrativo: 1, ..Default::default() }, ..Default::default() }; let player = PlayerState::new(); let plantilla = EventTemplate { peso_base: 10, ..Default::default() }; let ponderados = ponderar_eventos(vec![&plantilla], &world, &player); assert_eq!(ponderados[0].0, 10.0); }",
    "fn test_instanciar_evento_selecciona_npc_con_deuda() { let world = WorldState::new(); let player = PlayerState { relaciones: vec![NpcRelation { npc_id: String::from(\"arguelles\"), deuda: 2, ..Default::default() }], ..Default::default() }; let plantilla = EventTemplate { npc_pool: vec![String::from(\"arguelles\"), String::from(\"gallardo\")], ..Default::default() }; let evento = instanciar_evento(&plantilla, &world, &player); assert_eq!(evento.npc_id, \"arguelles\"); }",
    "fn test_generar_eventos_jornada_devuelve_ranuras() { let world = WorldState::new(); let player = PlayerState::new(); let memory = MemoryState::new(); let plantillas = vec![EventTemplate { ..Default::default() }]; let eventos = generar_eventos_jornada(&world, &player, &memory, &plantillas, 2); assert_eq!(eventos.len(), 2); }"
  ],
  "dependencies": [
    "serde",
    "serde_yaml"
  ],
  "notes": "Ubicar en repo/rust/crates/game_core/src/generador_eventos.rs. Importar: use crate::{world_state::WorldState, player_state::PlayerState, memory_state::MemoryState};. Definir structs: EventTemplate (id, familia, funcion_principal, peso_base, precondiciones, npc_pool, opciones, cooldown_jornadas), Precondiciones (mundo: Vec<(String, String, String)>, jugador: Vec<(String, String, String)>, etiquetas_unlock: Vec<String>), EventInstance (id, familia, npc_id, espacio_id, opciones_visibles, consecuencias). No incluir textos narrativos. Usar u8 para pesos y deltas. Las precondiciones son tuplas (variable, operador, valor)."
}
